SELECT prc.*,
(select s.meaning from sys_code_value_b_v s where s.code = 'PLI.INSPECTION_METHOD' and s.code_value = prc.collection_method) collection_method_desc, (select s.meaning from sys_code_value_b_v s where s.code = 'PLI.INSPECTION_METHOD' and s.code_value = prc.collection_method) collection_method_n,
(select wm_concat(fat.file_name) from fnd_atm_attachment fat, fnd_atm_attachment_multi faam where fat.attachment_id = faam.attachment_id and faam.table_name = 'PLM_RENT_COLLECTION' and faam.table_pk_value = prc.rent_collection_id) attachment_name FROM plm_rent_collection prc where 1=1
and prc.contract_id = #{contractId}
and prc.collection_status = #{collectionStatus}

mapper.update:
update
plm_rent_collection prc
set
prc.collection_status=#{collectionStatus}
WHERE
prc.proc_inst_id=#{procInstId}
